#!/bin/bash
# Microbench top-level build: cube / vector / memory / scalar / fixp
# Each category has its own compile.all that builds every case.
# fixp is hand-maintained (one source, active -D modes); the other four are
# table-generated by gen_cases.py.

set -u
SCRIPT_DIR=$(cd "$(dirname "$0")" && pwd)
cd "$SCRIPT_DIR"

CATEGORY=${1:-all}
FAILURES=""

run_category() {
    dir=$1
    label=$2
    echo ""
    echo ">>> $label"
    if ! (cd "$dir" && bash compile.all); then
        FAILURES="$FAILURES $dir"
    fi
}
compile_cube()   { run_category cube "matrix (TMA/CUBE direct)"; }
compile_vector() { run_category vector "vector (TEPL)"; }
compile_memory() { run_category memory "memory (TLSU)"; }
compile_scalar() { run_category scalar "scalar (GPR ALU)"; }
compile_fixp()   { run_category fixp "fixp (FPATR/quant TMATMUL)"; }

case "$CATEGORY" in
    cube)   compile_cube ;;
    vector) compile_vector ;;
    memory) compile_memory ;;
    scalar) compile_scalar ;;
    fixp)   compile_fixp ;;
    all)
        compile_cube
        compile_vector
        compile_memory
        compile_scalar
        compile_fixp
        ;;
    *)
        echo "Usage: $0 [cube|vector|memory|scalar|fixp|all]"
        exit 1
        ;;
esac

echo ""
echo "=========================================="
if [ -n "$FAILURES" ]; then
    echo "Microbench build FAILED for:$FAILURES"
    echo "=========================================="
    exit 1
fi
echo "Microbench build completed for: $CATEGORY"
echo "=========================================="
